// Generated by OrchestKit Claude Plugin
// Created: 2026-08-01

/**
 * Task Usage Signal — shared reader for "has this session created any tasks?"
 *
 * Source of truth is `.claude/logs/task-creations.jsonl`, written by the
 * TaskCreated dispatcher (task-created/creation-tracker) whose entries carry
 * `session_id`. That event is CC-native (shipped 2.1.84) and verified live on
 * this machine: TaskCreate calls appear in the log within seconds.
 *
 * Read strategy: tail-read the last TAIL_BYTES only. The log is append-only
 * and grows for months; a session's own entries are always at the end, and a
 * whole-file parse on every qualifying prompt would blow the UserPromptSubmit
 * budget for zero gain.
 *
 * FAILS CLOSED AS "true" (tasks exist). Both consumers use this signal to
 * decide whether to SPEAK (nudge, telemetry) — so an unreadable log must
 * produce silence, not a nudge that fires on every prompt forever. Quiet
 * failure beats noisy failure.
 */

import { existsSync, openSync, readSync, closeSync, fstatSync } from 'node:fs';
import { join } from 'node:path';

const TAIL_BYTES = 16 * 1024;

/** True when task-creations.jsonl's tail contains an entry for this session. */
export function sessionHasTasks(projectDir: string, sessionId: string): boolean {
  if (!projectDir || !sessionId) return true; // cannot tell -> stay quiet
  const logPath = join(projectDir, '.claude', 'logs', 'task-creations.jsonl');
  if (!existsSync(logPath)) return false; // no log ever written -> genuinely no tasks

  let fd: number | undefined;
  try {
    fd = openSync(logPath, 'r');
    const size = fstatSync(fd).size;
    const start = Math.max(0, size - TAIL_BYTES);
    const buf = Buffer.alloc(size - start);
    readSync(fd, buf, 0, buf.length, start);
    // Substring check, not JSON parse: entries are one object per line and the
    // session_id value is a UUID — a quoted-substring hit is unambiguous, and
    // parsing a possibly mid-line tail would throw on the first partial row.
    return buf.toString('utf8').includes(`"session_id":"${sessionId}"`);
  } catch {
    return true; // unreadable -> stay quiet
  } finally {
    if (fd !== undefined) {
      try {
        closeSync(fd);
      } catch {
        /* ignore */
      }
    }
  }
}
